// Small shared pieces for the word screens.
import { useTranslation } from "react-i18next";
import { LEARN_LANGS, type LearnLang } from "@shared/enums";
import { cn } from "@/lib/utils";

/** Marks content generated by AI and not yet verified by an adult. */
export function AiBadge() {
  const { t } = useTranslation();
  return (
    <span
      title={t("words.aiBadgeHint")}
      className="ml-2 rounded bg-amber-100 px-1.5 py-0.5 text-xs font-semibold text-amber-900 dark:bg-amber-900/40 dark:text-amber-200"
    >
      {t("words.aiBadge")}
    </span>
  );
}

type LangChipsProps = {
  value: LearnLang | null;
  onChange: (lang: LearnLang | null) => void;
  /** Adds an "All" chip (value null), used by the library filter. */
  allowAll?: boolean;
  label: string;
};

export function LangChips({ value, onChange, allowAll, label }: LangChipsProps) {
  const { t } = useTranslation();
  const options: (LearnLang | null)[] = allowAll ? [null, ...LEARN_LANGS] : [...LEARN_LANGS];
  return (
    <div role="group" aria-label={label} className="flex gap-2">
      {options.map((lang) => (
        <button
          key={lang ?? "all"}
          type="button"
          aria-pressed={value === lang}
          onClick={() => onChange(lang)}
          className={cn(
            "min-h-11 flex-1 rounded-lg border px-3 text-sm outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
            value === lang ? "border-primary bg-primary text-primary-foreground" : "bg-background hover:bg-accent",
          )}
        >
          {lang ? t(`langs.${lang}`) : t("words.filterAll")}
        </button>
      ))}
    </div>
  );
}
